from __future__ import annotations

from textwrap import dedent


def render_mvp_page() -> str:
    return dedent(
        r"""
        <!doctype html>
        <html lang="zh-CN">
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width,initial-scale=1">
          <title>SAG 独立测评工作台</title>
          <style>
            :root{--ink:#172033;--muted:#667381;--line:#dce4e9;--bg:#f2f6f7;--card:#fff;--brand:#167c80;--brand2:#0f5960;--accent:#ef7c45;--good:#14804a;--bad:#c94336;--warn:#b36b00}
            *{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--bg);font:14px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}
            button,input,select,textarea{font:inherit}.app{display:grid;grid-template-columns:280px 1fr;min-height:100vh}
            aside{background:#13232d;color:#eef8f8;padding:24px 18px;position:sticky;top:0;height:100vh;overflow:auto}.brand{font-size:20px;font-weight:800}.brand small{display:block;color:#8fb0b4;font-size:11px;letter-spacing:.12em;margin-top:4px}
            .side-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:22px 0}.side-actions button{padding:9px;border-radius:8px;border:1px solid #ffffff2c;background:#ffffff10;color:white;cursor:pointer}.side-actions .primary{background:var(--brand);border-color:var(--brand)}
            .side-title{font-size:11px;color:#8fb0b4;text-transform:uppercase;letter-spacing:.12em;margin:22px 6px 8px}.project-item{display:block;width:100%;text-align:left;background:transparent;color:#dcebed;border:0;border-radius:9px;padding:10px 11px;cursor:pointer}.project-item:hover,.project-item.active{background:#ffffff16}.project-item small{display:block;color:#8fb0b4;margin-top:2px}
            main{padding:30px;max-width:1500px;width:100%;margin:auto}.topbar{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:22px}.topbar h1{margin:0;font-size:28px}.topbar p{margin:5px 0 0;color:var(--muted)}
            .btn{border:0;border-radius:9px;padding:10px 14px;cursor:pointer;font-weight:700;background:#e8eef0;color:var(--ink)}.btn.primary{background:var(--brand);color:white}.btn.accent{background:var(--accent);color:white}.btn.small{padding:6px 9px;font-size:12px}.btn:disabled{opacity:.5;cursor:not-allowed}
            .tabs{display:flex;gap:6px;border-bottom:1px solid var(--line);margin-bottom:20px;overflow:auto}.tab{border:0;background:transparent;padding:11px 14px;border-bottom:3px solid transparent;cursor:pointer;color:var(--muted);white-space:nowrap}.tab.active{color:var(--brand);border-color:var(--brand);font-weight:800}
            .cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:20px}.card,.panel{background:var(--card);border:1px solid var(--line);border-radius:12px;box-shadow:0 5px 18px #1720330a}.card{padding:18px}.card span{color:var(--muted);font-size:12px}.card strong{display:block;font-size:27px;margin-top:6px;color:var(--brand)}
            .grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}.panel{padding:18px;margin-bottom:16px}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.panel h2{font-size:17px;margin:0}.hint{color:var(--muted);font-size:12px}
            table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:10px 9px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:#52616e;font-size:11px;text-transform:uppercase;letter-spacing:.04em}tr:last-child td{border-bottom:0}.empty{color:var(--muted);text-align:center;padding:32px}
            .badge{display:inline-block;border-radius:999px;padding:3px 8px;background:#edf2f4;font-size:11px}.badge.achieved{color:var(--good);background:#e9f7ef}.badge.not_achieved{color:var(--bad);background:#fff0ee}.badge.partial{color:var(--warn);background:#fff5e5}
            .form-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.form-grid .wide{grid-column:span 2}.form-grid input,.form-grid select,.form-grid textarea{width:100%;border:1px solid var(--line);border-radius:8px;padding:9px;background:white}.form-grid textarea{min-height:72px;resize:vertical}.form-grid button{align-self:end}
            .alert{padding:11px 13px;border-radius:9px;background:#fff2eb;color:#98451e;margin:7px 0}.welcome{min-height:70vh;display:grid;place-items:center;text-align:center}.welcome-box{max-width:660px}.welcome h1{font-size:38px;margin-bottom:8px}.welcome p{font-size:16px;color:var(--muted)}.welcome .btn{margin:8px 4px}
            dialog{border:0;border-radius:14px;box-shadow:0 30px 90px #0005;padding:0;max-width:620px;width:calc(100% - 32px)}dialog::backdrop{background:#10182088}.dialog-body{padding:22px}.dialog-body h2{margin-top:0}.dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:16px}
            .toast{position:fixed;right:24px;bottom:24px;background:#172033;color:white;padding:12px 16px;border-radius:9px;opacity:0;transform:translateY(10px);transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:none}.raw{white-space:pre-wrap;max-width:440px;max-height:150px;overflow:auto;color:#42515d}
            @media(max-width:1000px){.app{grid-template-columns:1fr}aside{position:relative;height:auto}.cards{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr 1fr}}
            @media(max-width:600px){main{padding:18px}.cards,.form-grid{grid-template-columns:1fr}.form-grid .wide{grid-column:auto}}
          </style>
        </head>
        <body>
        <div class="app">
          <aside>
            <div class="brand">SAG 测评台<small>SEO / GEO INDEPENDENT AUDIT</small></div>
            <div class="side-actions"><button class="primary" onclick="openClientDialog()">新建客户</button><button onclick="seedDemo()">载入演示</button></div>
            <div class="side-title">测评项目</div><div id="project-list"><div class="hint">加载中...</div></div>
            <div class="side-title">系统</div>
            <button class="project-item" onclick="window.open('/docs','_blank')">API 文档<small>OpenAPI / Swagger</small></button>
            <button class="project-item" onclick="window.open('/console','_blank')">采集调试台<small>原始 collect / analyze</small></button>
          </aside>
          <main id="main"><div class="welcome"><div class="welcome-box"><h1>独立验证服务效果</h1><p>围绕合同承诺，保存 SEO/GEO 原始证据，人工复核后生成可打印报告，并按固定口径持续复测。</p><button class="btn primary" onclick="seedDemo()">用演示数据体验</button><button class="btn" onclick="openClientDialog()">创建第一个客户</button></div></div></main>
        </div>
        <dialog id="dialog"><form class="dialog-body" id="dialog-form"><h2 id="dialog-title"></h2><div id="dialog-fields" class="form-grid"></div><div class="dialog-actions"><button type="button" class="btn" onclick="closeDialog()">取消</button><button class="btn primary">保存</button></div></form></dialog>
        <div class="toast" id="toast"></div>
        <script>
          const state={projects:[],project:null,dashboard:null,tab:'overview'};
          const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
          const statusName=v=>({trial:'试用',active:'启用',paused:'暂停',draft:'草稿',running:'执行中',completed:'已完成',partial:'部分完成',failed:'失败',pending:'待核验',achieved:'已达成',not_achieved:'未达成',unverifiable:'无法判断',reviewed:'已复核'}[v]||v);
          async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});if(!r.ok){let e={};try{e=await r.json()}catch{}throw new Error(e.detail||`请求失败 ${r.status}`)}return r.headers.get('content-type')?.includes('json')?r.json():r.text()}
          function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2300)}
          async function loadProjects(){state.projects=await api('/api/projects');document.querySelector('#project-list').innerHTML=state.projects.length?state.projects.map(p=>`<button class="project-item ${state.project?.id===p.id?'active':''}" onclick="loadProject(${p.id})">${esc(p.name)}<small>${esc(p.client_name)} · ${esc(statusName(p.subscription_status))}</small></button>`).join(''):'<div class="hint">暂无项目</div>'}
          async function loadProject(id){state.project=await api(`/api/projects/${id}`);state.dashboard=await api(`/api/projects/${id}/dashboard`);await loadProjects();render()}
          function tabs(){return `<div class="tabs">${[['overview','总览'],['assessment','评分与建议'],['seo','SEO数据'],['geo','GEO检测'],['reports','报告']].map(([k,n])=>`<button class="tab ${state.tab===k?'active':''}" onclick="switchTab('${k}')">${n}</button>`).join('')}</div>`}
          async function switchTab(tab){state.tab=tab;render()}
          function shell(content){const p=state.project;document.querySelector('#main').innerHTML=`<div class="topbar"><div><h1>${esc(p.name)}</h1><p>${esc(p.client_name)} · ${esc(p.brand_name)} · ${esc(p.domain)}</p></div><div><button class="btn" onclick="openEditProjectDialog()">编辑项目</button> <button class="btn" onclick="openProjectDialog()">新建项目</button></div></div>${tabs()}${content}`}
          function render(){if(!state.project)return;({overview:renderOverview,assessment:renderAssessment,commitments:renderCommitments,seo:renderSeo,geo:renderGeo,reports:renderReports}[state.tab])()}
          async function renderAssessment(){const a=await api(`/api/projects/${state.project.id}/assessment`);shell(`<div class="cards"><div class="card"><span>综合可见度评分</span><strong>${a.overall_score==null?'-':a.overall_score}</strong><span>100 分制</span></div><div class="card"><span>SEO 实测评分</span><strong>${a.seo.score==null?'-':a.seo.score}</strong><span>${esc(a.seo.latest_date||'尚无实测')}</span></div><div class="card"><span>GEO 实测评分</span><strong>${a.geo.score==null?'-':a.geo.score}</strong><span>${esc(a.geo.run_at||'尚无实测')}</span></div></div><section class="panel"><div class="panel-head"><h2>评分说明</h2><span class="hint">仅基于已留存实测</span></div><p>${esc(a.scoring_note)}</p><p class="hint">SEO 评分来自关键词排名；GEO 评分来自 AI 回答中的品牌提及、位置与官网引用。缺失维度不补分。</p></section><section class="panel"><div class="panel-head"><h2>网站与 AI 内容优化建议</h2><span class="hint">按实测缺口生成</span></div>${a.recommendations.length?a.recommendations.map(x=>`<div class="evidence-item"><b>${esc(x.priority==='high'?'高优先级':x.priority==='medium'?'中优先级':'低优先级')} · ${esc(x.dimension)} · ${esc(x.title)}</b><p>${esc(x.description)}</p></div>`).join(''):'<div class="empty">当前实测数据表现良好；请继续保持固定关键词、问题和平台复测。</div>'}</section><section class="panel"><h2>实测边界</h2><p>搜索排名需按关键词、搜索引擎、地区/语言和采样时间复核。AI 结果需保留平台、模型、测试时间、完整提问及原始回答；模型变化会影响回答，不能把单次结果当作永久排名。</p></section>`) }
          function renderOverview(){const d=state.dashboard,g=d.geo,c=d.commitments;const alerts=d.alerts.map(a=>`<div class="alert">${esc(a.message)}</div>`).join('');shell(`<div class="cards"><div class="card"><span>合同承诺</span><strong>${c.total}</strong></div><div class="card"><span>已核验</span><strong>${c.assessed}</strong></div><div class="card"><span>承诺达成率</span><strong>${c.achievement_rate==null?'-':c.achievement_rate+'%'}</strong></div><div class="card"><span>GEO提及率</span><strong>${g.mention_rate==null?'-':g.mention_rate+'%'}</strong><span>${g.change==null?'无上期对比':(g.change>0?'+':'')+g.change+' 个百分点'}</span></div></div>${alerts}<div class="grid2"><section class="panel"><div class="panel-head"><h2>SEO 最新趋势</h2><span class="hint">${esc(d.seo.latest_date||'暂无数据')}</span></div>${d.seo.metrics.length?`<table><tr><th>指标</th><th>本期</th><th>上期</th><th>变化</th></tr>${d.seo.metrics.map(m=>`<tr><td>${esc(m.metric_name)}</td><td>${m.value} ${esc(m.unit)}</td><td>${m.previous_value??'-'}</td><td>${m.change==null?'-':m.change+'%'}</td></tr>`).join('')}</table>`:'<div class="empty">录入两期SEO指标后显示趋势</div>'}</section><section class="panel"><div class="panel-head"><h2>GEO 平台表现</h2><span class="hint">${esc(g.run?.run_at||'暂无采样')}</span></div>${g.platforms.length?`<table><tr><th>平台</th><th>回答</th><th>提及率</th><th>准确率</th></tr>${g.platforms.map(x=>`<tr><td>${esc(x.platform)}</td><td>${x.queries}</td><td>${x.mention_rate}%</td><td>${x.accurate_rate==null?'待复核':x.accurate_rate+'%'}</td></tr>`).join('')}</table>`:'<div class="empty">尚无GEO结果</div>'}${g.competitors?.length?`<h3>竞品提及</h3><table><tr><th>竞品</th><th>提及率</th></tr>${g.competitors.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.mention_rate}%</td></tr>`).join('')}</table>`:''}</section></div><section class="panel"><div class="panel-head"><h2>测评范围</h2><button class="btn primary small" onclick="openCompetitorDialog()">添加竞品</button></div><p><b>监测频率：</b>${esc(state.project.cadence==='quarterly'?'季度':'月度')}　<b>订阅状态：</b>${esc(statusName(state.project.subscription_status))}　<b>预警阈值：</b>${state.project.alert_threshold}%</p><p><b>竞品：</b>${state.project.competitors.length?state.project.competitors.map(x=>esc(x.name)).join('、'):'尚未设置'}</p></section>`) }
          async function renderCommitments(){const rows=await api(`/api/projects/${state.project.id}/commitments`),demoNotice=state.project.domain==='demo.example.com'?'<div class="alert">当前为演示项目：这 4 条用于展示合同核验流程，可直接编辑；真实项目请替换为合同承诺及独立采集的数据。</div>':'';shell(`<section class="panel"><div class="panel-head"><h2>服务商承诺与实际结果</h2><button class="btn primary small" onclick="openCommitmentDialog()">新增承诺</button></div>${demoNotice}${rows.length?`<table><tr><th>类别</th><th>指标</th><th>承诺</th><th>实际</th><th>判断</th><th>证据</th><th>操作</th></tr>${rows.map(x=>`<tr><td>${esc(x.category)}</td><td>${esc(x.metric_name)}</td><td>${esc(x.target_operator)} ${x.target_value??'-'} ${esc(x.unit)}</td><td>${x.actual_value??'-'}</td><td><span class="badge ${esc(x.achievement_status)}">${esc(statusName(x.achievement_status))}</span></td><td>${esc(x.evidence_source||'待补')}</td><td><button class="btn small" onclick='openCommitmentEditDialog(${JSON.stringify(x)})'>编辑</button></td></tr>`).join('')}</table>`:'<div class="empty">逐条录入合同承诺，报告才能判断是否达成</div>'}</section>`) }
          async function renderSeo(){const data=await api(`/api/projects/${state.project.id}/seo`);shell(`<section class="panel"><div class="panel-head"><h2>SEO 指标</h2><button class="btn primary small" onclick="openMetricDialog()">新增指标</button></div>${data.metrics.length?`<table><tr><th>日期</th><th>指标</th><th>数值</th><th>来源</th></tr>${data.metrics.map(x=>`<tr><td>${esc(x.captured_at)}</td><td>${esc(x.metric_name)}</td><td>${x.value} ${esc(x.unit)}</td><td>${esc(x.source)}</td></tr>`).join('')}</table>`:'<div class="empty">暂无SEO指标</div>'}</section><section class="panel"><div class="panel-head"><h2>关键词排名</h2><div><button class="btn small" onclick="openCsvDialog()">导入CSV</button> <button class="btn primary small" onclick="openRankingDialog()">新增排名</button></div></div>${data.rankings.length?`<table><tr><th>日期</th><th>关键词</th><th>分类</th><th>引擎</th><th>排名</th><th>来源</th></tr>${data.rankings.slice(0,100).map(x=>`<tr><td>${esc(x.captured_at)}</td><td>${esc(x.keyword)}</td><td>${esc(x.category)}</td><td>${esc(x.engine)}</td><td>${x.position??'100+'}</td><td>${esc(x.source)}</td></tr>`).join('')}</table>`:'<div class="empty">支持字段：keyword/关键词、position/排名、search_volume/搜索量、engine/搜索引擎、captured_at/日期、source/数据源</div>'}</section>`) }
          async function renderGeo(){const sets=await api(`/api/projects/${state.project.id}/geo/question-sets`),runs=await api(`/api/projects/${state.project.id}/geo/runs`);shell(`<div class="grid2"><section class="panel"><div class="panel-head"><h2>版本化问题库</h2><button class="btn primary small" onclick="openQuestionSetDialog()">新建版本</button></div>${sets.length?`<table><tr><th>名称</th><th>版本</th><th>问题数</th><th></th></tr>${sets.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.version)}</td><td>${x.question_count}</td><td><button class="btn small" onclick="openQuestionDialog(${x.id})">加问题</button></td></tr>`).join('')}</table>`:'<div class="empty">先建立认知期、比较期、决策期问题库</div>'}</section><section class="panel"><div class="panel-head"><h2>检测批次</h2><div><button class="btn small" onclick='openGeoBatchDialog(${JSON.stringify(sets)})'>批量调用模型</button> <button class="btn primary small" onclick='openGeoRunDialog(${JSON.stringify(sets)})'>人工批次</button></div></div>${runs.length?`<table><tr><th>日期</th><th>问题库</th><th>状态</th><th>回答/复核</th><th></th></tr>${runs.map(x=>`<tr><td>${esc(x.run_at)}</td><td>${esc(x.question_set_name)} ${esc(x.version)}</td><td>${esc(statusName(x.status))}</td><td>${x.response_count}/${x.reviewed_count||0}</td><td><button class="btn small" onclick="showRun(${x.id},${x.question_set_id})">查看</button></td></tr>`).join('')}</table>`:'<div class="empty">创建批次后可人工录入或调用已配置模型</div>'}</section></div><section class="panel" id="run-detail"><div class="empty">选择检测批次查看原始回答</div></section>`) }
          async function showRun(runId,setId){const responses=await api(`/api/geo/runs/${runId}/responses`),questions=await api(`/api/geo/question-sets/${setId}/questions`);document.querySelector('#run-detail').innerHTML=`<div class="panel-head"><h2>原始回答与人工复核</h2><button class="btn primary small" onclick='openResponseDialog(${runId},${JSON.stringify(questions)})'>录入回答</button></div>${responses.length?`<table><tr><th>问题</th><th>平台</th><th>原始回答</th><th>提及</th><th>准确</th><th>复核</th></tr>${responses.map(x=>`<tr><td>${esc(x.question)}</td><td>${esc(x.platform)}</td><td><div class="raw">${esc(x.raw_response)}</div></td><td>${x.brand_mentioned?'是':'否'}</td><td>${x.accurate==null?'待核验':x.accurate?'准确':'不准确'}</td><td><button class="btn small" onclick='openReviewDialog(${JSON.stringify(x)})'>复核</button></td></tr>`).join('')}</table>`:'<div class="empty">尚无回答；可人工录入各平台结果</div>'}` }
          async function renderReports(){const reports=await api(`/api/projects/${state.project.id}/reports`);shell(`<section class="panel"><div class="panel-head"><div><h2>报告生成与归档</h2><div class="hint">自动填充数据，结论由测评人员复核</div></div><div><button class="btn" onclick="window.open('/reports/${state.project.id}/preview','_blank')">实时预览</button> <button class="btn primary" onclick="openReportDialog()">归档报告</button></div></div>${reports.length?`<table><tr><th>标题</th><th>周期</th><th>状态</th><th>创建时间</th><th></th></tr>${reports.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.period_start||'-')} 至 ${esc(x.period_end||'-')}</td><td>${esc(x.status)}</td><td>${esc(x.created_at)}</td><td><button class="btn small" onclick="window.open('/reports/${state.project.id}/${x.id}','_blank')">查看/打印</button></td></tr>`).join('')}</table>`:'<div class="empty">实时预览确认后，将报告结论归档为固定版本</div>'}</section>`) }
          function openDialog(title,fields,onSubmit){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-fields').innerHTML=fields;const form=document.querySelector('#dialog-form');form.onsubmit=async e=>{e.preventDefault();try{await onSubmit(Object.fromEntries(new FormData(form)));closeDialog();toast('已保存');await loadProject(state.project?.id||state.projects[0]?.id); }catch(err){toast(err.message)}};document.querySelector('#dialog').showModal()}
          function closeDialog(){document.querySelector('#dialog').close()}
          const input=(name,label,type='text',value='',cls='',required=true)=>`<label class="${cls}"><span class="hint">${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'step="any"':''} ${required?'required':''}></label>`;
          function openClientDialog(){openDialog('新建客户',input('name','企业名称')+input('brand_name','品牌名称')+input('domain','官网域名')+input('industry','行业'),async d=>{const c=await api('/api/clients',{method:'POST',body:JSON.stringify(d)});setTimeout(()=>openProjectDialog(c.id),120)})}
          async function openProjectDialog(clientId){const clients=await api('/api/clients');openDialog('新建测评项目',`<label><span class="hint">客户</span><select name="client_id">${clients.map(c=>`<option value="${c.id}" ${c.id==clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${input('name','项目名称')}${input('service_provider','SEO/GEO服务商')}${input('period_start','开始日期','date',new Date().toISOString().slice(0,10))}${input('period_end','结束日期','date',new Date().toISOString().slice(0,10))}<label><span class="hint">监测频率</span><select name="cadence"><option value="monthly">月度</option><option value="quarterly">季度</option></select></label><label><span class="hint">订阅状态</span><select name="subscription_status"><option value="trial">试用</option><option value="active">启用</option><option value="paused">暂停</option></select></label>${input('alert_threshold','预警阈值（%）','number',20)}`,async d=>{const p=await api('/api/projects',{method:'POST',body:JSON.stringify({...d,client_id:+d.client_id,alert_threshold:+d.alert_threshold})});await loadProject(p.id)})}
          async function openEditProjectDialog(){const p=state.project,clients=await api('/api/clients');openDialog('编辑测评项目',`<label><span class="hint">客户</span><select name="client_id">${clients.map(c=>`<option value="${c.id}" ${c.id==p.client_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${input('name','项目名称','text',p.name)}${input('service_provider','SEO/GEO服务商','text',p.service_provider||'')}${input('period_start','开始日期','date',p.period_start||'')}${input('period_end','结束日期','date',p.period_end||'')}<label><span class="hint">监测频率</span><select name="cadence"><option value="monthly" ${p.cadence==='monthly'?'selected':''}>月度</option><option value="quarterly" ${p.cadence==='quarterly'?'selected':''}>季度</option></select></label><label><span class="hint">订阅状态</span><select name="subscription_status"><option value="trial" ${p.subscription_status==='trial'?'selected':''}>试用</option><option value="active" ${p.subscription_status==='active'?'selected':''}>启用</option><option value="paused" ${p.subscription_status==='paused'?'selected':''}>暂停</option></select></label>${input('alert_threshold','预警阈值（%）','number',p.alert_threshold)}<label><span class="hint">项目状态</span><select name="status"><option value="active" ${p.status==='active'?'selected':''}>进行中</option><option value="paused" ${p.status==='paused'?'selected':''}>暂停</option></select></label>`,d=>api(`/api/projects/${p.id}`,{method:'PUT',body:JSON.stringify({...d,client_id:+d.client_id,alert_threshold:+d.alert_threshold})}))}
          function openCompetitorDialog(){openDialog('添加竞品',input('name','竞品名称')+input('domain','竞品域名','text',''),d=>api(`/api/projects/${state.project.id}/competitors`,{method:'POST',body:JSON.stringify(d)}))}
          const numberOrNull=value=>value===''?null:+value;
          function openKeywordTargetDialog(){openDialog('添加测试关键词',input('keyword','关键词')+`<label><span class="hint">搜索引擎</span><select name="engine"><option value="baidu">百度</option><option value="google">Google</option><option value="bing">Bing</option></select></label>`+input('target_position','期望排名','number','','',false)+input('target_url','目标页面','text','','',false),d=>api(`/api/projects/${state.project.id}/keyword-targets`,{method:'POST',body:JSON.stringify({...d,target_position:numberOrNull(d.target_position)})}))}
          function commitmentFields(x={}){return input('category','类别','text',x.category||'SEO')+input('metric_name','指标名称','text',x.metric_name||'')+`<label><span class="hint">目标关系</span><select name="target_operator">${['>=','>','=','<=','<'].map(v=>`<option value="${v}" ${(x.target_operator||'>=')===v?'selected':''}>${v}</option>`).join('')}</select></label>`+input('target_value','目标值','number',x.target_value??'')+input('unit','单位','text',x.unit||'')+input('actual_value','实际值','number',x.actual_value??'','',false)+input('due_date','验收日期','date',x.due_date||'','',false)+`<label><span class="hint">达成判断</span><select name="achievement_status">${[['pending','待核验'],['achieved','已达成'],['partial','部分达成'],['not_achieved','未达成'],['unverifiable','无法判断']].map(([v,n])=>`<option value="${v}" ${(x.achievement_status||'pending')===v?'selected':''}>${n}</option>`).join('')}</select></label>`+input('evidence_source','证据来源','text',x.evidence_source||'')+`<label class="wide"><span class="hint">合同原文</span><textarea name="source_clause">${esc(x.source_clause||'')}</textarea></label><label class="wide"><span class="hint">核验备注</span><textarea name="notes">${esc(x.notes||'')}</textarea></label>`}
          function commitmentPayload(d){return {...d,target_value:numberOrNull(d.target_value),actual_value:numberOrNull(d.actual_value),due_date:d.due_date||null}}
          function openCommitmentDialog(){openDialog('新增合同承诺',commitmentFields(),d=>api(`/api/projects/${state.project.id}/commitments`,{method:'POST',body:JSON.stringify(commitmentPayload(d))}))}
          function openCommitmentEditDialog(x){openDialog('编辑合同承诺',commitmentFields(x),d=>api(`/api/commitments/${x.id}`,{method:'PUT',body:JSON.stringify(commitmentPayload(d))}))}
          function openMetricDialog(){openDialog('新增SEO指标',input('captured_at','采样日期','date',new Date().toISOString().slice(0,10))+input('source','数据来源','text','5118 / 爱站网')+input('metric_key','指标编码','text','organic_traffic')+input('metric_name','指标名称','text','自然流量')+input('value','数值','number')+input('unit','单位','text','访问'),d=>api(`/api/projects/${state.project.id}/seo/metrics`,{method:'POST',body:JSON.stringify({...d,value:+d.value})}))}
          function openRankingDialog(){openDialog('新增关键词排名',input('captured_at','采样日期','date',new Date().toISOString().slice(0,10))+input('source','数据来源','text','5118')+input('keyword','关键词')+input('category','分类','text','commercial')+input('engine','搜索引擎','text','baidu')+input('position','排名','number')+input('search_volume','搜索量','number',0)+input('target_url','目标页面'),d=>api(`/api/projects/${state.project.id}/seo/rankings`,{method:'POST',body:JSON.stringify({...d,position:d.position?+d.position:null,search_volume:d.search_volume?+d.search_volume:null})}))}
          function openCsvDialog(){openDialog('导入SEO CSV',input('default_captured_at','默认采样日期','date',new Date().toISOString().slice(0,10))+input('default_source','默认数据源','text','CSV import')+`<label class="wide"><span class="hint">CSV内容</span><textarea name="content" placeholder="keyword,position,search_volume,engine&#10;工业空压机厂家,16,1200,baidu" required></textarea></label>`,d=>api(`/api/projects/${state.project.id}/seo/import`,{method:'POST',body:JSON.stringify({...d,filename:'pasted.csv'})}))}
          function openQuestionSetDialog(){openDialog('新建问题库版本',input('name','问题库名称')+input('version','版本','text','v1.0')+`<label><span class="hint">状态</span><select name="status"><option value="draft">草稿</option><option value="active">启用</option></select></label>`,d=>api(`/api/projects/${state.project.id}/geo/question-sets`,{method:'POST',body:JSON.stringify(d)}))}
          function openQuestionDialog(setId){openDialog('新增GEO问题',`<label><span class="hint">用户意图</span><select name="intent"><option>认知期</option><option>比较期</option><option>决策期</option></select></label>`+`<label class="wide"><span class="hint">真实口语化问题</span><textarea name="question" required></textarea></label>`+`<label class="wide"><span class="hint">预期事实/核验点</span><textarea name="expected_facts"></textarea></label>`,d=>api(`/api/geo/question-sets/${setId}/questions`,{method:'POST',body:JSON.stringify(d)}))}
          function openGeoRunDialog(sets){if(!sets.length)return toast('请先创建问题库');openDialog('新建检测批次',`<label><span class="hint">问题库</span><select name="question_set_id">${sets.map(x=>`<option value="${x.id}">${esc(x.name)} ${esc(x.version)}</option>`).join('')}</select></label>`+input('run_at','采样日期','date',new Date().toISOString().slice(0,10))+input('notes','采样条件','text','人工采样'),d=>api(`/api/projects/${state.project.id}/geo/runs`,{method:'POST',body:JSON.stringify({...d,question_set_id:+d.question_set_id})}))}
          function openGeoBatchDialog(sets){if(!sets.length)return toast('请先创建问题库');openDialog('批量调用已配置模型',`<label><span class="hint">问题库</span><select name="question_set_id">${sets.map(x=>`<option value="${x.id}">${esc(x.name)} ${esc(x.version)}</option>`).join('')}</select></label>`+input('run_at','采样日期','date',new Date().toISOString().slice(0,10))+input('platform','平台显示名','text','DeepSeek')+`<label><span class="hint">接入方式</span><select name="provider"><option value="openrouter">OpenRouter</option><option value="qianfan">百度千帆</option></select></label>`+input('model','模型ID','text','openai/gpt-4.1-mini')+input('notes','采样条件','text','API批量采样'),d=>api(`/api/projects/${state.project.id}/geo/runs/batch`,{method:'POST',body:JSON.stringify({question_set_id:+d.question_set_id,run_at:d.run_at,notes:d.notes,providers:[{platform:d.platform,provider:d.provider,model:d.model}]})}))}
          function openResponseDialog(runId,questions){openDialog('录入AI原始回答',`<label class="wide"><span class="hint">问题</span><select name="question_id">${questions.map(q=>`<option value="${q.id}">${esc(q.question)}</option>`).join('')}</select></label>`+input('platform','AI平台','text','DeepSeek')+input('model','模型/版本','text','')+`<label class="wide"><span class="hint">完整原始回答</span><textarea name="raw_response" required></textarea></label>`,d=>api(`/api/geo/runs/${runId}/responses`,{method:'POST',body:JSON.stringify({...d,question_id:+d.question_id})}))}
          function openReviewDialog(x){openDialog('人工复核GEO结果',`<label><span class="hint">品牌被提及</span><select name="brand_mentioned"><option value="true" ${x.brand_mentioned?'selected':''}>是</option><option value="false" ${!x.brand_mentioned?'selected':''}>否</option></select></label>`+input('mention_position','提及位置','number',x.mention_position||'')+`<label><span class="hint">提及准确性</span><select name="accurate"><option value="true" ${x.accurate===1?'selected':''}>准确</option><option value="false" ${x.accurate===0?'selected':''}>不准确</option></select></label><label><span class="hint">进入推荐</span><select name="recommended"><option value="true" ${x.recommended?'selected':''}>是</option><option value="false" ${!x.recommended?'selected':''}>否</option></select></label>`+input('competitor_mentions','竞品（逗号分隔）','text',(x.competitor_mentions||[]).join(','))+input('misinformation','错误/过时信息','text',x.misinformation||'')+`<label class="wide"><span class="hint">复核备注</span><textarea name="reviewer_notes">${esc(x.reviewer_notes||'')}</textarea></label>`,d=>api(`/api/geo/responses/${x.id}/review`,{method:'PUT',body:JSON.stringify({...d,brand_mentioned:d.brand_mentioned==='true',accurate:d.accurate==='true',recommended:d.recommended==='true',mention_position:d.mention_position?+d.mention_position:null,competitor_mentions:d.competitor_mentions.split(',').map(s=>s.trim()).filter(Boolean),cited_source:!!x.cited_source})}).then(()=>showRun(x.geo_run_id,x.question_set_id)))}
          function openReportDialog(){openDialog('归档报告',input('period_start','开始日期','date',state.project.period_start||'')+input('period_end','结束日期','date',state.project.period_end||'')+`<label class="wide"><span class="hint">标题</span><input name="title" value="SEO / GEO 服务效果独立第三方测评报告"></label><label class="wide"><span class="hint">执行摘要（留空则自动生成）</span><textarea name="executive_summary"></textarea></label><label class="wide"><span class="hint">综合结论</span><textarea name="conclusion"></textarea></label><label class="wide"><span class="hint">行动建议</span><textarea name="recommendations"></textarea></label>`,d=>api(`/api/projects/${state.project.id}/reports`,{method:'POST',body:JSON.stringify(d)}))}
          async function seedDemo(){try{const x=await api('/api/demo/seed',{method:'POST',body:'{}'});await loadProjects();await loadProject(x.project_id);toast(x.created?'演示数据已创建':'已打开现有演示项目')}catch(e){toast(e.message)}}
          async function renderAssessment(){const a=await api(`/api/projects/${state.project.id}/assessment`),targets=await api(`/api/projects/${state.project.id}/keyword-targets`);shell(`<div class="cards"><div class="card"><span>综合可见度评分</span><strong>${a.overall_score==null?'-':a.overall_score}</strong><span>100 分制</span></div><div class="card"><span>SEO 实测评分</span><strong>${a.seo.score==null?'-':a.seo.score}</strong><span>${esc(a.seo.latest_date||'尚无实测')}</span></div><div class="card"><span>GEO 实测评分</span><strong>${a.geo.score==null?'-':a.geo.score}</strong><span>${esc(a.geo.run_at||'尚无实测')}</span></div></div><section class="panel"><div class="panel-head"><div><h2>测试关键词</h2><div class="hint">每个关键词按指定搜索引擎记录实测排名。</div></div><button class="btn primary small" onclick="openKeywordTargetDialog()">添加关键词</button></div>${targets.length?`<table><tr><th>关键词</th><th>引擎</th><th>期望排名</th><th>目标页面</th></tr>${targets.map(x=>`<tr><td>${esc(x.keyword)}</td><td>${esc(x.engine)}</td><td>${x.target_position??'-'}</td><td>${esc(x.target_url||'-')}</td></tr>`).join('')}</table>`:'<div class="empty">先添加品牌词、产品词、问题词；然后在 SEO 数据页导入或录入各引擎的实测排名。</div>'}</section><section class="panel"><h2>网站与 AI 内容优化建议</h2>${a.recommendations.length?a.recommendations.map(x=>`<div class="evidence-item"><b>${esc(x.priority==='high'?'高优先级':x.priority==='medium'?'中优先级':'低优先级')} · ${esc(x.dimension)} · ${esc(x.title)}</b><p>${esc(x.description)}</p></div>`).join(''):'<div class="empty">暂无待优化缺口。</div>'}</section><section class="panel"><h2>评分与实测边界</h2><p>${esc(a.scoring_note)}</p><p class="hint">评分只使用已保存的实测数据。AI 页面会保留完整问题和逐平台原始回答；报告会按采样时间、模型和平台呈现，避免将单次回答说成永久排名。</p></section>`) }
          function renderOverview(){const d=state.dashboard,a=d.assessment,g=d.geo;shell(`<div class="cards"><div class="card"><span>综合可见度评分</span><strong>${a.overall_score??'-'}</strong><span>仅基于已保存实测</span></div><div class="card"><span>SEO 评分</span><strong>${a.seo.score??'-'}</strong><span>${esc(a.seo.latest_date||'暂无采样')}</span></div><div class="card"><span>GEO 评分</span><strong>${a.geo.score??'-'}</strong><span>${esc(a.geo.run_at||'暂无采样')}</span></div><div class="card"><span>GEO 品牌提及率</span><strong>${g.mention_rate==null?'-':g.mention_rate+'%'}</strong></div></div><section class="panel"><h2>测试范围</h2><p><b>SEO：</b>百度、Google、Bing、360、搜狗、神马、Yahoo、Yandex、DuckDuckGo。</p><p><b>GEO：</b>ChatGPT、Gemini、Claude、Perplexity、Grok、DeepSeek、通义千问、豆包、腾讯元宝、Kimi、文心一言、智谱清言。</p><p class="hint">演示数据用于展示字段、评分与报告结构，不能视为这些平台的真实线上结果。</p></section><section class="panel"><h2>GEO 平台表现</h2>${g.platforms.length?`<table><tr><th>平台</th><th>回答</th><th>提及率</th><th>准确率</th></tr>${g.platforms.map(x=>`<tr><td>${esc(x.platform)}</td><td>${x.queries}</td><td>${x.mention_rate}%</td><td>${x.accurate_rate??'-'}%</td></tr>`).join('')}</table>`:'<div class="empty">尚无 AI 平台实测结果。</div>'}</section>`) }
          async function renderGeo(){const sets=await api(`/api/projects/${state.project.id}/geo/question-sets`),runs=await api(`/api/projects/${state.project.id}/geo/runs`);shell(`<div class="grid2"><section class="panel"><div class="panel-head"><h2>版本化问题库</h2><button class="btn primary small" onclick="openQuestionSetDialog()">新建版本</button></div>${sets.length?`<table><tr><th>名称</th><th>版本</th><th>问题数</th><th>操作</th></tr>${sets.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.version)}</td><td>${x.question_count}</td><td><button class="btn small" onclick="showQuestionSet(${x.id})">查看问题</button> <button class="btn small" onclick="openQuestionDialog(${x.id})">添加问题</button></td></tr>`).join('')}</table>`:'<div class="empty">建立认知、比较、决策阶段的问题库后再开始 AI 测试。</div>'}</section><section class="panel"><div class="panel-head"><h2>检测批次</h2><div><button class="btn small" onclick='openGeoBatchDialog(${JSON.stringify(sets)})'>批量调用模型</button> <button class="btn primary small" onclick='openGeoRunDialog(${JSON.stringify(sets)})'>人工批次</button></div></div>${runs.length?`<table><tr><th>日期</th><th>问题库</th><th>状态</th><th>回答/复核</th><th>操作</th></tr>${runs.map(x=>`<tr><td>${esc(x.run_at)}</td><td>${esc(x.question_set_name)} ${esc(x.version)}</td><td>${esc(statusName(x.status))}</td><td>${x.response_count}/${x.reviewed_count||0}</td><td><button class="btn small" onclick="showRun(${x.id},${x.question_set_id})">查看回答</button></td></tr>`).join('')}</table>`:'<div class="empty">创建批次后可人工录入或调用已配置模型。</div>'}</section></div><section class="panel" id="question-detail"><div class="empty">点击“查看问题”查看问题库的全部测试语句、意图和核验点。</div></section><section class="panel" id="run-detail"><div class="empty">选择检测批次查看逐平台原始回答。</div></section>`) }
          async function showQuestionSet(setId){const questions=await api(`/api/geo/question-sets/${setId}/questions`);document.querySelector('#question-detail').innerHTML=`<div class="panel-head"><h2>问题库详细内容</h2><span class="hint">共 ${questions.length} 条</span></div>${questions.length?`<table><tr><th>意图</th><th>测试语句</th><th>权重</th><th>预期事实 / 核验点</th></tr>${questions.map(x=>`<tr><td>${esc(x.intent)}</td><td>${esc(x.question)}</td><td>${x.weight}</td><td>${esc(x.expected_facts||'-')}</td></tr>`).join('')}</table>`:'<div class="empty">此版本尚未添加问题。</div>'}`}
          function openKeywordTargetDialog(){openDialog('添加测试关键词',input('keyword','关键词')+`<label><span class="hint">搜索引擎</span><select name="engine"><option value="baidu">百度</option><option value="google">Google</option><option value="bing">Bing</option><option value="360">360</option><option value="sogou">搜狗</option><option value="shenma">神马</option></select></label>`+input('region_name','指定地域','text','全国')+input('language','语言','text','zh-CN')+input('target_position','期望排名','number','','',false)+input('target_url','目标页面','text','','',false),d=>api(`/api/projects/${state.project.id}/keyword-targets`,{method:'POST',body:JSON.stringify({...d,target_position:numberOrNull(d.target_position)})}))}
          function openRankingDialog(){openDialog('新增关键词实测排名',input('captured_at','采样日期','date',new Date().toISOString().slice(0,10))+input('source','数据来源','text','5118')+input('keyword','关键词')+input('category','分类','text','commercial')+input('engine','搜索引擎','text','baidu')+input('region_name','指定地域','text','全国')+input('language','语言','text','zh-CN')+input('position','排名','number')+input('search_volume','搜索量','number',0)+input('target_url','目标页面'),d=>api(`/api/projects/${state.project.id}/seo/rankings`,{method:'POST',body:JSON.stringify({...d,position:numberOrNull(d.position),search_volume:numberOrNull(d.search_volume)})}))}
          async function renderSeo(){const data=await api(`/api/projects/${state.project.id}/seo`);shell(`<section class="panel"><div class="panel-head"><h2>SEO 指标</h2><button class="btn primary small" onclick="openMetricDialog()">新增指标</button></div>${data.metrics.length?`<table><tr><th>日期</th><th>指标</th><th>数值</th><th>来源</th><th>指标作用</th></tr>${data.metrics.map(x=>`<tr><td>${esc(x.captured_at)}</td><td>${esc(x.metric_name)}</td><td>${x.value} ${esc(x.unit)}</td><td>${esc(x.source)}</td><td>${esc(x.notes||'-')}</td></tr>`).join('')}</table>`:'<div class="empty">暂无 SEO 指标。</div>'}</section><section class="panel"><div class="panel-head"><h2>关键词实测排名</h2><div><button class="btn small" onclick="openCsvDialog()">导入 CSV</button> <button class="btn primary small" onclick="openRankingDialog()">新增排名</button></div></div><p class="hint">地域与语言是排名测试条件：不同地域的同一关键词必须分别记录和比较。</p>${data.rankings.length?`<table><tr><th>日期</th><th>关键词</th><th>引擎</th><th>地域</th><th>语言</th><th>排名</th><th>来源</th></tr>${data.rankings.slice(0,100).map(x=>`<tr><td>${esc(x.captured_at)}</td><td>${esc(x.keyword)}</td><td>${esc(x.engine)}</td><td>${esc(x.region_name||'全国')}</td><td>${esc(x.language||'zh-CN')}</td><td>${x.position??'100+'}</td><td>${esc(x.source)}</td></tr>`).join('')}</table>`:'<div class="empty">CSV 支持字段：keyword、position、engine、region_name/地域、language/语言、captured_at、source。</div>'}</section>`) }
          loadProjects();
        </script>
        </body></html>
        """
    )
